import {Lab,RAM_START} from './lab.js';
import {ISA,INSTRUCTIONS,hex,disassemble} from './isa.js';
import {assemble,stripComment} from './assembler.js';
import {exportHex,importHex} from './hex.js';
import {EXAMPLES,idProgram,waveProgram} from './examples.js';
import {Oscilloscope,formatTime,formatHz} from './scope.js';

const $=id=>document.getElementById(id),all=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const lab=new Lab();lab.cpu.pc=RAM_START;
const scope=new Oscilloscope(lab);
const state={view:'bench',running:false,build:null,dirty:true,output:'build',memoryPage:0x2000,fileName:'experiment.asm',temporaryBreak:null,sourceBreaks:new Set(),sourceBreakAddresses:new Set(),lastRegs:{},lastDraw:0,lastFrame:0,slowCredit:0,log:[],imported:false,needsDraw:true,renderedRunning:null};
let toastTimeout,saveTimeout,editApply;
const on=(id,event,fn)=>$(id).addEventListener(event,e=>{try{const p=fn(e);if(p?.catch)p.catch(reportError);}catch(error){reportError(error);}finally{state.needsDraw=true;}});
function reportError(e){notify(e.message||String(e),true);$('footer-message').textContent=e.message||String(e);}
function notify(message,error=false){const el=$('toast');el.textContent=message;el.classList.toggle('error',error);el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),error?6000:3300);}
function text(id,value){const node=$(id);if(node&&node.textContent!==String(value))node.textContent=value;}
function value(id,v){if(document.activeElement!==$(id))$(id).value=String(v);}
function checked(id,v){$(id).checked=!!v;}
function readHex(id,max=65535){const s=$(id).value.trim().replace(/^0x/i,'').replace(/H$/i,'');if(!/^[\da-f]+$/i.test(s))throw new Error('Enter a hexadecimal value');const n=parseInt(s,16);if(n>max)throw new Error('Value must be between 0 and '+hex(max,max>255?4:2)+'H');return n;}
function numeric(id,min,max){const n=Number($(id).value);if(!Number.isFinite(n)||n<min||n>max)throw new Error(`Value must be between ${min} and ${max}`);return n;}
function download(name,content,type='text/plain;charset=utf-8'){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function log(message,type='info'){state.log.push({message,type});state.log=state.log.slice(-30);if(state.output==='build')renderOutput();$('footer-message').textContent=message;}
function autosave(){clearTimeout(saveTimeout);saveTimeout=setTimeout(()=>{try{localStorage.setItem('8085-bench-draft',JSON.stringify({source:$('source').value,id:lab.id,fileName:state.fileName,sourceBreaks:[...state.sourceBreaks]}));}catch{}},400);}
function setView(view){state.view=view;all('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));all('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));text('view-title',({bench:'Workbench',interface:'Interfacing',scope:'Oscilloscope',memory:'Memory',reference:'Reference'})[view]);renderAll();window.scrollTo({top:0,behavior:'instant'});}
function pause(message=null){state.running=false;state.temporaryBreak=null;state.needsDraw=true;renderRunState();if(message)log(message);}
function renderRunState(){const cpu=lab.cpu,el=$('state-pill'),label=cpu.fault?'FAULT':cpu.hold?'HOLD':cpu.halted?'HALTED':state.running?'RUNNING':state.build?'PAUSED':'READY';el.classList.toggle('paused',cpu.halted||!state.running);el.classList.toggle('error',!!cpu.fault);if(el.querySelector('span').textContent!==label)el.querySelector('span').textContent=label;if(state.renderedRunning!==state.running){$('run-btn').classList.toggle('running',state.running);$('run-btn').innerHTML=state.running?'❚❚ <span>Pause</span>':'▶ <span>Run</span>';state.renderedRunning=state.running;}text('global-time',formatTime(lab.time));text('footer-pc','PC '+hex(cpu.pc,4)+'H');}

const opNames=new Set(INSTRUCTIONS.map(e=>e.mnemonic));
function highlightLine(s){let out='',last=0;const pattern=/;.*$|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|[A-Za-z_?.@][\w?.@]*:|\b(?:0x[\da-f]+|[\da-f]+H|[01]+B|\d+)\b|\b[A-Za-z_?.@][\w?.@]*\b/gi;for(const m of s.matchAll(pattern)){out+=esc(s.slice(last,m.index));const token=m[0],u=token.toUpperCase();let cls=token.startsWith(';')?'syntax-comment':token[0]==='"'||token[0]==="'"?'syntax-string':token.endsWith(':')?'syntax-label':opNames.has(u)?'syntax-op':['ORG','DB','DW','DS','EQU','SET','END','ALIGN','VECTOR','MACRO','ENDM','REPT'].includes(u)?'syntax-directive':/^[\d]|^[A-F\d]+H$/i.test(token)?'syntax-number':['A','B','C','D','E','H','L','M','SP','PSW','BC','DE','HL'].includes(u)?'syntax-reg':null;out+=cls?`<span class="${cls}">${esc(token)}</span>`:esc(token);last=m.index+token.length;}return out+esc(s.slice(last));}
function renderSource(){const lines=$('source').value.split('\n');$('code-highlight').innerHTML=lines.map((line,i)=>`<span class="code-line" data-line="${i+1}">${highlightLine(line)||' '}</span>`).join('');$('line-gutter').innerHTML='<div id="gutter-lines">'+lines.map((_,i)=>`<div class="line-number${state.sourceBreaks.has(i+1)?' breakpoint':''}" data-line="${i+1}" role="button" tabindex="0" aria-label="Toggle breakpoint at line ${i+1}" aria-pressed="${state.sourceBreaks.has(i+1)}" title="Toggle breakpoint at line ${i+1}">${i+1}</div>`).join('')+'</div>';syncEditorScroll();markPCLine();updateCaret();}
function syncEditorScroll(){$('code-highlight').style.transform=`translate(${- $('source').scrollLeft}px,${- $('source').scrollTop}px)`;const gutter=$('gutter-lines');if(gutter)gutter.style.transform=`translateY(${- $('source').scrollTop}px)`;}
function currentSourceLine(){return !state.dirty&&state.build?.listing?.find(r=>r.address===lab.cpu.pc&&r.bytes.length)?.line;}
function markPCLine(){const line=currentSourceLine();all('.code-line.current,.line-number.executing').forEach(e=>e.classList.remove('current','executing'));if(line){document.querySelector(`.code-line[data-line="${line}"]`)?.classList.add('current');document.querySelector(`.line-number[data-line="${line}"]`)?.classList.add('executing');}}
function updateCaret(){const source=$('source'),before=source.value.slice(0,source.selectionStart),lines=before.split('\n');text('caret-pos',`Ln ${lines.length}, Col ${lines.at(-1).length+1}`);}
function setSource(source,name='experiment.asm'){pause();$('source').value=source;state.fileName=name;text('source-name',name);state.dirty=true;state.imported=false;state.sourceBreaks.clear();state.sourceBreakAddresses.forEach(a=>lab.breakpoints.delete(a));state.sourceBreakAddresses.clear();$('dirty-dot').style.display='inline';renderSource();autosave();}
function buildAndLoad(quiet=false){pause();const started=performance.now(),result=assemble($('source').value);state.build=result;state.imported=false;state.log=[];state.output='build';all('[data-output]').forEach(b=>b.classList.toggle('active',b.dataset.output==='build'));all('.code-line.error-line').forEach(e=>e.classList.remove('error-line'));
  if(!result.ok){for(const error of result.errors)document.querySelector(`.code-line[data-line="${error.line}"]`)?.classList.add('error-line');text('build-count',result.errors.length);log(`Build failed · ${result.errors.length} error${result.errors.length===1?'':'s'}`,'error');renderOutput();if(!quiet)notify('Assembly failed. Select an error in the Build panel.',true);return false;}
  lab.load(result);scope.clear();state.sourceBreakAddresses.forEach(a=>lab.breakpoints.delete(a));state.sourceBreakAddresses.clear();for(const line of state.sourceBreaks){const row=result.listing.find(r=>r.line===line&&r.bytes.length);if(row){lab.breakpoints.add(row.address);state.sourceBreakAddresses.add(row.address);}}
  state.dirty=false;$('dirty-dot').style.display='none';text('build-count','✓');log(`Assembled ${result.byteCount} bytes · entry ${hex(result.entry,4)}H · ${(performance.now()-started).toFixed(1)} ms`,'success');log('Loaded into user RAM. CPU and peripherals reset.');renderAll();if(!quiet)notify('Build successful. Ready to run.');return true;
}
function run(){if(state.running){pause('Paused at '+hex(lab.cpu.pc,4)+'H');return;}if((state.dirty||!state.build)&&!state.imported&&!buildAndLoad(true))return;if(lab.cpu.fault)throw new Error('Reset or reassemble before continuing after a CPU fault');state.running=true;state.lastFrame=performance.now();state.slowCredit=0;state.skipBreakpoint=lab.cpu.pc;renderRunState();}
function step(){pause();if((state.dirty||!state.build)&&!state.imported&&!buildAndLoad(true))return;lab.watchHit=null;const instruction=lab.cpu.step();if(instruction.interrupt)log(instruction.text);else if(!instruction.halted&&!instruction.hold)log(`${hex(instruction.pc,4)}H · ${instruction.entry.mnemonic} · ${instruction.cycles} T-states`);renderAll();scrollToPC();}
function stepOver(){if((state.dirty||!state.build)&&!state.imported&&!buildAndLoad(true))return;const d=disassemble(a=>lab.peek(a),lab.cpu.pc);if(d.entry&&(d.entry.mnemonic==='CALL'||d.entry.mnemonic==='RST'||d.entry.mnemonic.startsWith('C')&&d.entry.group==='Branch')){state.temporaryBreak={pc:lab.cpu.pc+d.size&65535,sp:lab.cpu.sp};state.running=true;state.skipBreakpoint=lab.cpu.pc;state.lastFrame=performance.now();renderRunState();}else step();}
function reset(){pause();const entry=state.build?.entry??0x2000;lab.reset({entry});for(const v of state.build?.vectors||[])lab.setVector(v.address,v.target);scope.clear();log('Reset · user RAM retained · PC '+hex(entry,4)+'H');renderAll();}
function scrollToPC(){const line=currentSourceLine();if(!line)return;const y=(line-1)*23,area=$('source');if(y<area.scrollTop||y>area.scrollTop+area.clientHeight-46){area.scrollTop=Math.max(0,y-area.clientHeight/3);syncEditorScroll();}}
function renderOutput(){const area=$('output-area');$('console-input-row').classList.toggle('hidden',state.output!=='console');if(state.output==='build'){if(!state.build&&!state.log.length)return;area.innerHTML=state.log.map(l=>`<div class="build-message ${l.type==='error'?'red-text':l.type==='success'?'lime-text':''}">${esc(l.message)}</div>`).join('')+(state.build?.ok===false?state.build.errors.map(e=>`<button class="build-error" data-error-line="${e.line}">Line ${e.line} · ${esc(e.message)}</button>`).join(''):'');}
  else if(state.output==='console'){const scroll=area.scrollTop+area.clientHeight>=area.scrollHeight-20;area.innerHTML='<pre>'+esc(lab.consoleOut||'Console ready. RST 1 outputs A; RST 3 prints the string at HL.')+'</pre>';if(scroll)area.scrollTop=area.scrollHeight;}
  else if(state.output==='listing'){area.innerHTML=state.build?.ok?'<table>'+state.build.listing.filter(r=>r.bytes.length).map(r=>`<tr class="${r.address===lab.cpu.pc?'current':''}"><td class="cyan-text">${hex(r.address,4)}</td><td>${r.bytes.slice(0,8).map(v=>hex(v)).join(' ')}${r.bytes.length>8?' …':''}</td><td>${esc(stripComment(r.text))}</td></tr>`).join('')+'</table>':'Assemble successfully to view the listing.';}
  else if(state.output==='symbols'){area.innerHTML=state.build?.ok?'<table>'+Object.entries(state.build.symbols).sort((a,b)=>a[1]-b[1]).map(([name,v])=>`<tr><td>${esc(name)}</td><td class="amber-text">${hex(v,4)}H</td><td>${v}</td></tr>`).join('')+'</table>':'No symbols yet.';}}

function initializeRegisters(){const names=['A','F','B','C','D','E','H','L','PC','SP'];$('register-grid').innerHTML=names.map(n=>`<button class="register${n==='PC'||n==='SP'?' wide':''}" data-register="${n}" title="Edit ${n}"><span>${n}</span><strong id="reg-${n}">00</strong></button>`).join('');$('flag-row').innerHTML=['S','Z','AC','P','CY'].map(n=>`<button class="flag" data-flag="${n}" title="Toggle ${n}">${n} <small id="flag-${n}">0</small></button>`).join('');}
function renderCPU(){const cpu=lab.cpu;for(const n of ['A','F','B','C','D','E','H','L','PC','SP']){const v=n==='PC'?cpu.pc:n==='SP'?cpu.sp:n==='F'?cpu.flags:cpu.r[n];text('reg-'+n,hex(v,n==='PC'||n==='SP'?4:2));$(`reg-${n}`).parentElement.classList.toggle('changed',state.lastRegs[n]!==undefined&&state.lastRegs[n]!==v);state.lastRegs[n]=v;}for(const [n,v]of Object.entries(cpu.f)){text('flag-'+n,v);$(`flag-${n}`).parentElement.classList.toggle('on',!!v);}text('instruction-count',cpu.instructions.toLocaleString()+' instr · '+cpu.cycles.toLocaleString()+' T');const next=disassemble(a=>lab.peek(a),cpu.pc);text('next-instruction',hex(cpu.pc,4)+'H  '+next.text);text('sod-status','SOD = '+cpu.sod);text('console-count',lab.consoleOut.length||'');renderRunState();markPCLine();}
function initializeID(){$('id-led-board').innerHTML=[0,1,2].map(p=>`<div class="id-port"><div class="id-port-head"><span>PORT ${'ABC'[p]}</span><span id="id-hex-${p}">00H</span></div><div class="id-digits inactive" id="id-digits-${p}">--</div><div class="led-row">${Array.from({length:8},(_,i)=>`<i class="led low" id="id-led-${p}-${7-i}" title="P${'ABC'[p]}${7-i}"></i>`).join('')}</div><div class="bit-labels">${[7,6,5,4,3,2,1,0].map(b=>`<span>${b}</span>`).join('')}</div><div class="port-binary" id="id-binary-${p}">0000 0000</div></div>`).join('');}
function renderID(){const ppi=lab.ppis[1];for(let p=0;p<3;p++){const mask=ppi.outputMask(p),pins=ppi.pins(p),v=pins^(lab.idActiveLow?255:0),digits=(v>>4)<=9&&(v&15)<=9?String(v>>4)+String(v&15):'??';text('id-hex-'+p,hex(pins)+'H');text('id-digits-'+p,mask===255?digits:'--');$('id-digits-'+p).classList.toggle('inactive',mask!==255);text('id-binary-'+p,v.toString(2).padStart(8,'0').slice(0,4)+' '+v.toString(2).padStart(8,'0').slice(4));for(let b=0;b<8;b++){const el=$(`id-led-${p}-${b}`);el.classList.toggle('on',!!(v&mask&1<<b));el.classList.toggle('low',!(mask&1<<b));el.title=`P${'ABC'[p]}${b} = ${pins>>b&1}${mask&1<<b?' (output)':' (input / high impedance)'}`;}}
  text('id-control-status',ppi.control===0x80?'Mode 0 · all ports output':'CW '+hex(ppi.control)+'H · mixed I/O');text('id-map-label',mapLabel(1));}
function mapLabel(i){const m=lab.mapping[i],n=m.space==='io'?2:4;return hex(m.base,n)+'H–'+hex(m.base+3,n)+'H';}
function renderAnalog(){text('analog-map-label',mapLabel(0));text('dac-chip-name',lab.dac.profile);text('adc-chip-name',lab.adc.profile);text('dac-readout',lab.dac.voltage.toFixed(3)+' V');text('dac-code',hex(lab.dac.code)+'H');text('adc-readout',(lab.adc.code*lab.adc.vref/256).toFixed(3)+' V');text('adc-code',hex(lab.adc.code)+'H');text('adc-status',lab.adc.busy?'Converting · CH'+lab.adc.channel:lab.adc.profile==='0804'?'ADC idle · /INTR '+lab.adc.intr:'ADC idle · EOC '+lab.adc.eoc);$('eoc-dot').style.background=lab.adc.busy?'var(--amber)':'var(--lime)';}
function loadExample(id){const e=EXAMPLES.find(x=>x.id===id);if(!e)return;if(e.profile)lab.adc.profile=e.profile;else if(id==='adc')lab.adc.profile='0808';if(e.disconnect)lab.wiring.analogEnabled=false;
  if(!['id','sine','square','triangle','saw'].includes(id))lab.mapping=[{space:'io',base:0x80},{space:'io',base:0x90}];
  if(e.memoryMapped)lab.configureMapping(1,'memory',0xF000);else if(id==='welcome') {lab.mapping=[{space:'io',base:0x80},{space:'io',base:0x90}];lab.wiring={dac:'A',adc:'B',control:'C',analogEnabled:true,irq:'none'};lab.adc.profile='0808';}
  let source=typeof e.source==='function'?e.source():e.source;
  if(id==='id')source=idProgram(lab.id,lab.mapping[1].base,lab.idActiveLow,lab.mapping[1].space);
  if(['sine','square','triangle','saw'].includes(id)){lab.wiring.dac='A';lab.wiring.adc='B';lab.wiring.analogEnabled=true;source=waveProgram(id,lab.mapping[0]);}
  if(id==='adc'||id==='adc04'){lab.mapping[0]={space:'io',base:0x80};lab.wiring={dac:'A',adc:'B',control:'C',analogEnabled:true,irq:'none'};}
  if(id==='interrupt'||id==='handshake'){if(id==='interrupt')lab.mapping[1]={space:'io',base:0x90};else lab.mapping[0]={space:'io',base:0x80};}
  setSource(source,e.id+'.asm');syncSettings();setView('bench');notify(e.description);$('example-select').value='';}

function initializePPI(){$('ppi-controls').innerHTML=[0,1].map(i=>`<section class="panel peripheral-panel ppi-card" data-ppi="${i}"><div class="panel-heading"><div class="panel-title"><i class="small-square ${i?'amber':'cyan'}"></i> 8255 #${i+1} · ${i?'ID / LEDs':'Analog / general I/O'}</div><span class="tag" id="ppi-address-${i}">${mapLabel(i)}</span></div><div class="ppi-map"><label>Address space<select id="ppi-space-${i}"><option value="io">I/O mapped</option><option value="memory">Memory mapped</option></select></label><label>Base (hex)<input id="ppi-base-${i}" class="hex-input" value="${hex(lab.mapping[i].base)}" maxlength="5"></label><button class="button small" data-ppi-action="map" data-ppi="${i}">Apply mapping</button></div><div class="form-grid" id="ppi-builder-${i}"><label>Group A mode<select id="ppi-modeA-${i}"><option value="0">0 · Basic I/O</option><option value="1">1 · Strobed I/O</option><option value="2">2 · Bidirectional</option></select></label><label>Port A<select id="ppi-dirA-${i}"><option value="1">Input</option><option value="0">Output</option></select></label><label>Group B mode<select id="ppi-modeB-${i}"><option value="0">0 · Basic I/O</option><option value="1">1 · Strobed I/O</option></select></label><label>Port B<select id="ppi-dirB-${i}"><option value="1">Input</option><option value="0">Output</option></select></label><label>PC upper (7–4)<select id="ppi-dirCH-${i}"><option value="1">Input</option><option value="0">Output</option></select></label><label>PC lower (3–0)<select id="ppi-dirCL-${i}"><option value="1">Input</option><option value="0">Output</option></select></label></div><div class="control-word"><span>CONTROL WORD</span><code id="ppi-control-${i}">9BH</code><button class="button small" data-ppi-action="configure" data-ppi="${i}">Write configuration</button><span id="ppi-draft-${i}">9BH</span></div><div>${[0,1,2].map(p=>`<div class="ppi-port-row"><code>P${'ABC'[p]}</code><span class="port-direction" id="ppi-direction-${i}-${p}">INPUT</span><div class="led-row">${[7,6,5,4,3,2,1,0].map(b=>`<button class="led" id="ppi-led-${i}-${p}-${b}" data-ppi="${i}" data-port="${p}" data-bit="${b}" data-ppi-action="switch" title="Toggle external P${'ABC'[p]}${b}"></button>`).join('')}</div><code class="hex-input" id="ppi-pins-${i}-${p}">FF</code><input id="ppi-ext-${i}-${p}" class="hex-input" value="FF" maxlength="3" aria-label="8255 ${i+1} port ${'ABC'[p]} external input"><button class="text-button" data-ppi-action="external" data-port="${p}" data-ppi="${i}">Set</button></div>`).join('')}</div><div class="ppi-manual"><label>Register<select id="ppi-register-${i}"><option value="0">Port A</option><option value="1">Port B</option><option value="2">Port C</option><option value="3">Control / BSR</option></select></label><label>Value (hex)<input id="ppi-write-${i}" class="hex-input" value="80" maxlength="3"></label><button class="button small" data-ppi-action="write" data-ppi="${i}">Write</button><button class="button small" data-ppi-action="read" data-ppi="${i}">Read</button><span id="ppi-read-${i}" class="mono quiet">—</span></div><div class="ppi-handshake">${['strobe','ack'].flatMap(type=>[0,1].map(p=>`<button class="button subtle small" data-ppi-action="${type}" data-port="${p}" data-ppi="${i}">${type==='strobe'?'STB':'ACK'} ${'AB'[p]} pulse</button>`)).join('')}</div><div class="ppi-status" id="ppi-status-${i}"></div>${i?'<label class="toggle-label inset"><input id="id-active-low" type="checkbox"> Active-low LED wiring</label>':'<p class="help-text">LEDs show actual pin levels. Click a bit to set its external input. Disconnect the analog harness to experiment freely with handshake modes.</p>'}</section>`).join('');
  for(let i=0;i<2;i++)all(`#ppi-builder-${i} select`).forEach(el=>el.addEventListener('change',()=>{text('ppi-draft-'+i,hex(draftControl(i))+'H');$('ppi-draft-'+i).classList.add('amber-text');}));
}
function draftControl(i){return 0x80|+$(`ppi-modeA-${i}`).value<<5|+$(`ppi-dirA-${i}`).value<<4|+$(`ppi-dirCH-${i}`).value<<3|+$(`ppi-modeB-${i}`).value<<2|+$(`ppi-dirB-${i}`).value<<1|+$(`ppi-dirCL-${i}`).value;}
function syncPPIBuilder(i){const p=lab.ppis[i],c=p.control;value('ppi-modeA-'+i,p.modeA);value('ppi-modeB-'+i,p.modeB);value('ppi-dirA-'+i,c>>4&1);value('ppi-dirB-'+i,c>>1&1);value('ppi-dirCH-'+i,c>>3&1);value('ppi-dirCL-'+i,c&1);text('ppi-draft-'+i,hex(c)+'H');$('ppi-draft-'+i).classList.remove('amber-text');}
function writePPI(i,p,v){const m=lab.mapping[i];if(m.space==='io')lab.output(m.base+p,v);else lab.write(m.base+p,v);}
function readPPI(i,p){const m=lab.mapping[i];return m.space==='io'?lab.input(m.base+p):lab.read(m.base+p);}
function ppiAction(button){const i=+button.dataset.ppi,p=+button.dataset.port,ppi=lab.ppis[i],action=button.dataset.ppiAction;
  if(action==='map'){lab.configureMapping(i,$(`ppi-space-${i}`).value,readHex('ppi-base-'+i));notify(`8255 #${i+1} mapped at ${mapLabel(i)}`);renderWiring();}
  else if(action==='configure'){writePPI(i,3,draftControl(i));syncPPIBuilder(i);notify('Control word written');}
  else if(action==='write'){writePPI(i,+$(`ppi-register-${i}`).value,readHex('ppi-write-'+i,255));syncPPIBuilder(i);}
  else if(action==='read'){const v=readPPI(i,+$(`ppi-register-${i}`).value);text('ppi-read-'+i,hex(v)+'H / '+v);}
  else if(action==='external'){ppi.setInput(p,readHex(`ppi-ext-${i}-${p}`,255));lab.sync();}
  else if(action==='switch'){ppi.setInput(p,ppi.external[p]^1<<+button.dataset.bit);lab.sync();}
  else if(action==='strobe'||action==='ack'){ppi.pulse(p,action);lab.sync();}
  renderAll();}
function renderPPI(){for(let i=0;i<2;i++){const p=lab.ppis[i];text('ppi-control-'+i,hex(p.control)+'H');text('ppi-address-'+i,mapLabel(i));for(let port=0;port<3;port++){const pins=p.pins(port),mask=p.outputMask(port);text(`ppi-direction-${i}-${port}`,mask===255?'OUTPUT':mask===0?'INPUT':'MIXED');text(`ppi-pins-${i}-${port}`,hex(pins));value(`ppi-ext-${i}-${port}`,hex(p.external[port]));for(let b=0;b<8;b++){const led=$(`ppi-led-${i}-${port}-${b}`);led.classList.toggle('on',!!(pins&1<<b));led.title=`P${'ABC'[port]}${b} = ${pins>>b&1} · ${mask&1<<b?'output':'input'} · click to toggle external input`;}}
    text('ppi-status-'+i,`A: mode ${p.modeA} · IBF=${p.ibf[0]} /OBF=${p.obf[0]} INTR=${p.intr[0]}  |  B: mode ${p.modeB} · IBF=${p.ibf[1]} /OBF=${p.obf[1]} INTR=${p.intr[1]}`);}}
function renderWiring(){const connected=lab.wiring.analogEnabled,adc04=lab.adc.profile==='0804';$('wiring-diagram').innerHTML=`<svg viewBox="0 0 1100 210" role="img" aria-label="8085 bus connects separately to two 8255 chips. 8255 one connects to ADC and DAC; 8255 two connects to six ID digits."><defs><pattern id="dots" width="15" height="15" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#2c414b"/></pattern></defs><rect width="1100" height="210" fill="url(#dots)"/><g fill="none" stroke="#4f6c76" stroke-width="2"><path d="M185 105 H270 V58 H335 M270 105 V160 H335"/></g><g font-family="Consolas,monospace"><rect x="60" y="67" width="125" height="76" rx="5" fill="#202d2d" stroke="#70836b"/><text x="123" y="100" text-anchor="middle" fill="#d1ee86" font-size="17">8085A</text><text x="123" y="120" text-anchor="middle" fill="#718b8d" font-size="9">ADDRESS + DATA BUS</text><text x="207" y="97" fill="#647e87" font-size="8">RD / WR</text><rect x="335" y="29" width="170" height="59" rx="5" fill="#172d31" stroke="#385c5b"/><text x="420" y="54" text-anchor="middle" fill="#65d9d1" font-size="13">8255 #1 · ${mapLabel(0)}</text><text x="420" y="73" text-anchor="middle" fill="#647e87" font-size="9">ANALOG INTERFACE</text><rect x="335" y="130" width="170" height="59" rx="5" fill="#2a2c24" stroke="#535940"/><text x="420" y="155" text-anchor="middle" fill="#f0bb73" font-size="13">8255 #2 · ${mapLabel(1)}</text><text x="420" y="174" text-anchor="middle" fill="#81866e" font-size="9">DEDICATED ID BOARD</text><g opacity="${connected?1:.2}"><path d="M505 45 H660" fill="none" stroke="#65d9d1" stroke-width="2"/><text x="565" y="37" fill="#688e8c" font-size="8">P${lab.wiring.dac} → D0–D7</text><rect x="660" y="22" width="130" height="45" rx="4" fill="#153336" stroke="#416763"/><text x="725" y="49" text-anchor="middle" fill="#65d9d1" font-size="13">DAC${lab.dac.profile}</text><path d="M790 45 H935" fill="none" stroke="#65d9d1" stroke-width="2"/><circle cx="949" cy="45" r="13" fill="#18292b" stroke="#65d9d1"/><text x="949" y="50" text-anchor="middle" fill="#65d9d1" font-size="15">∿</text><text x="949" y="22" text-anchor="middle" fill="#688e8c" font-size="8">SCOPE CH1</text><path d="M505 75 H590 V97 H660" fill="none" stroke="#f0bb73" stroke-width="2"/><text x="563" y="89" fill="#968260" font-size="8">P${lab.wiring.adc} ← DATA</text><rect x="660" y="76" width="130" height="45" rx="4" fill="#2b2f24" stroke="#6b6047"/><text x="725" y="103" text-anchor="middle" fill="#f0bb73" font-size="13">ADC${lab.adc.profile}</text><path d="M790 98 H935" fill="none" stroke="#f0bb73" stroke-width="2"/><text x="860" y="91" fill="#968260" font-size="8">ANALOG INPUT</text><text x="725" y="139" text-anchor="middle" fill="#647e87" font-size="8">PC ↔ ${adc04?'/WR, /RD, /INTR':'CHANNEL, ALE/START, EOC'}</text></g><path d="M505 159 H660" fill="none" stroke="#c2a46b" stroke-width="2"/>${[0,1,2].map(i=>`<rect x="${660+i*100}" y="147" width="81" height="35" rx="4" fill="#2e3323" stroke="#5a6342"/><text x="${700+i*100}" y="168" text-anchor="middle" fill="#e0bb76" font-size="13">P${'ABC'[i]} · ${lab.id.slice(i*2,i*2+2)}</text>`).join('')}</g></svg>`;
  text('wiring-note',`Default 8255 control word: ${lab.wiring.dac==='A'?'8AH':'98H'} (${lab.wiring.dac==='A'?'PA out / PB in':'PA in / PB out'} / PC upper in, lower out).`);
  text('wiring-pinout',adc04?'PC3: /WR · PC0: /RD · PC7: /INTR · ADC /CS tied low':'PC0–2: ADC channel · PC3: ALE + START · PC7: EOC · OE tied high');
}

function initializeChannels(){$('adc-channels').innerHTML=Array.from({length:8},(_,i)=>`<div class="channel-row" id="adc-channel-${i}"><span>IN${i}</span><select id="adc-source-${i}" aria-label="ADC channel ${i} source"><option value="generator">Generator</option><option value="dc">DC level</option><option value="dac">DAC loopback</option></select><input id="adc-dc-${i}" type="number" min="-20" max="20" step="0.1" value="2.5" aria-label="Channel ${i} DC level"><output id="adc-value-${i}">2.50 V</output></div>`).join('');$('manual-channel').innerHTML=Array.from({length:8},(_,i)=>`<option value="${i}">IN${i}</option>`).join('');for(let i=0;i<8;i++){on('adc-source-'+i,'change',e=>{lab.adc.sources[i]=e.target.value;renderPeripherals();});on('adc-dc-'+i,'change',()=>{lab.adc.dc[i]=numeric('adc-dc-'+i,-20,20);renderPeripherals();});}}
function renderPeripherals(){text('adc-time',formatTime(lab.adc.conversionSeconds));text('adc-conversion-info',lab.adc.conversions.toLocaleString()+' conversions');for(let i=0;i<8;i++){text('adc-value-'+i,lab.analogVoltage(i).toFixed(2)+' V');$('adc-channel-'+i).classList.toggle('active',i===lab.adc.channel);$('adc-dc-'+i).disabled=lab.adc.sources[i]!=='dc';$('adc-source-'+i).disabled=lab.adc.profile==='0804'&&i>0;}
  text('dac-full-code',hex(lab.dac.code)+'H / '+lab.dac.code);text('dac-current',(lab.dac.current*1000).toFixed(3)+' mA');text('dac-voltage',lab.dac.voltage.toFixed(3)+' V');value('dac-manual',lab.dac.code);text('dac-manual-value',lab.dac.code);}
function syncSettings(){value('cpu-clock',lab.clock);value('user-id',lab.id);checked('analog-connected',lab.wiring.analogEnabled);value('wire-dac',lab.wiring.dac);value('wire-adc',lab.wiring.adc);value('wire-irq',lab.wiring.irq);value('adc-profile',lab.adc.profile);value('adc-vref',lab.adc.vref);value('adc-clock',lab.adc.clock/1000);value('dac-profile',lab.dac.profile);value('dac-vref',lab.dac.reference);value('dac-rref',lab.dac.rref);value('dac-rload',lab.dac.rload);checked('dac-bipolar',lab.dac.bipolar);checked('id-active-low',lab.idActiveLow);value('scope-rate',lab.scopeRate);
  for(let i=0;i<2;i++){value('ppi-space-'+i,lab.mapping[i].space);value('ppi-base-'+i,hex(lab.mapping[i].base,lab.mapping[i].space==='io'?2:4));syncPPIBuilder(i);}for(let i=0;i<8;i++){value('adc-source-'+i,lab.adc.sources[i]);value('adc-dc-'+i,lab.adc.dc[i]);}for(const key of ['type','frequency','amplitude','offset','duty','phase','dc'])value('gen-'+key,lab.generator[key]);value('intr-vector',lab.cpu.intrOpcode);value('intr-call',hex(lab.cpu.intrAddress,4));checked('sid-input',lab.cpu.sid);checked('cpu-hold',lab.cpu.hold);value('cpu-waits',lab.cpu.waitStates);$('manual-channel').disabled=lab.adc.profile==='0804';renderWiring();updateWaveFrequency();}
function manualConversion(){if(!lab.wiring.analogEnabled)throw new Error('Connect the analog harness first');const channel=lab.adc.profile==='0804'?0:+$('manual-channel').value;writePPI(0,3,lab.wiring.adc==='B'?0x8A:0x98);if(lab.adc.profile==='0804'){writePPI(0,2,1);writePPI(0,2,9);}else {writePPI(0,2,channel|8);writePPI(0,2,channel);}lab.idle(lab.adc.conversionSeconds+1/lab.clock);if(lab.adc.profile==='0804')writePPI(0,2,8);const result=readPPI(0,lab.wiring.adc==='A'?0:1);log(`ADC CH${channel}: ${lab.adc.sampledVoltage.toFixed(3)} V → ${hex(result)}H (${result})`);renderAll();}

function renderMemory(){const base=state.memoryPage;const rows=['<thead><tr><th>ADDR</th>'+Array.from({length:16},(_,i)=>'<th>'+hex(i,1)+'</th>').join('')+'<th>ASCII</th></tr></thead><tbody>'];for(let row=0;row<16;row++){const a=base+row*16;rows.push('<tr><th>'+hex(a,4)+'</th>');let ascii='';for(let col=0;col<16;col++){const address=a+col,v=lab.peek(address),classes=[address===lab.cpu.pc?'pc':'',lab.changed.has(address)?'changed':'',address<RAM_START?'rom':'',lab.findDevice('memory',address)?'mapped':''].filter(Boolean).join(' ');rows.push(`<td><button class="memory-cell ${classes}" data-memory="${address}" title="${hex(address,4)}H = ${hex(v)}H (${v})">${hex(v)}</button></td>`);ascii+=v>=32&&v<=126?String.fromCharCode(v):'·';}rows.push('<td class="ascii">'+esc(ascii)+'</td></tr>');}rows.push('</tbody>');$('memory-table').innerHTML=rows.join('');text('memory-page-label',hex(base,4)+'H–'+hex(base+255,4)+'H');renderDisassembly();renderStack();renderBreaks();renderIO();renderTrace();}
function renderDisassembly(){let address=$('follow-pc').checked?lab.cpu.pc:state.memoryPage;const rows=[];for(let i=0;i<14;i++){const d=disassemble(a=>lab.peek(a),address);rows.push(`<div class="disasm-line${address===lab.cpu.pc?' current':''}${lab.breakpoints.has(address)?' breakpoint':''}"><button data-breakpoint="${address}" title="Toggle execution breakpoint">${hex(address,4)}</button><span class="disasm-bytes">${d.bytes.map(v=>hex(v)).join(' ')}</span><code>${esc(d.text)}</code></div>`);address=address+d.size&65535;}$('disassembly').innerHTML=rows.join('');}
function renderStack(){text('stack-pointer-label','SP '+hex(lab.cpu.sp,4)+'H');$('stack-view').innerHTML=Array.from({length:6},(_,i)=>{const a=lab.cpu.sp+i&65535,v=lab.peek(a);return `<div class="stack-row"><span>${hex(a,4)}H</span><code>${hex(v)}H</code><small>${i===0?'← SP':a<RAM_START?'ROM':''}</small></div>`;}).join('');}
function renderBreaks(){$('break-list').innerHTML=[...[...lab.breakpoints].map(a=>({a,type:'execute'})),...[...lab.watchpoints].map(([a,type])=>({a,type}))].map(b=>`<span class="break-chip">${hex(b.a,4)}H · ${b.type}<button data-remove-break="${b.a}" data-kind="${b.type}" aria-label="Remove breakpoint">×</button></span>`).join('')||'<span class="quiet" style="font-size:10px">No breakpoints or watchpoints.</span>';}
function renderIO(){const port=parseInt($('io-address').value,16)||0,base=port&0xE0;$('io-ports').innerHTML=Array.from({length:32},(_,i)=>{const a=base+i,d=lab.findDevice('io',a),v=d?d.ppi.peek(d.port):a===0xE1?+!!lab.consoleIn.length:lab.externalPorts[a];return `<div class="io-port${d?' mapped':''}" data-io="${a}" title="${d?'8255 #'+(d.index+1):'Generic port'}">${hex(a)} <b>${hex(v)}</b></div>`;}).join('');}
function renderTrace(){const filter=$('trace-filter').value;let points=lab.trace.points();if(filter==='io')points=points.filter(p=>['IN','OUT'].includes(p.type));if(filter==='memory')points=points.filter(p=>!['IN','OUT','ID'].includes(p.type));$('trace-table').innerHTML='<thead><tr><th>TIME</th><th>T-STATES</th><th>TYPE</th><th>ADDRESS</th><th>DATA</th><th>DEVICE</th></tr></thead><tbody>'+points.slice(-180).reverse().map(p=>`<tr><td class="mono">${formatTime(p.t)}</td><td class="mono">${p.cycles}</td><td><span class="trace-type">${esc(p.type)}</span></td><td class="mono">${hex(p.address,['IN','OUT','ID'].includes(p.type)?2:4)}H</td><td class="mono">${hex(p.value)}H</td><td>${esc(p.device)}</td></tr>`).join('')+'</tbody>';}
function toggleBreak(address){if(lab.breakpoints.has(address))lab.breakpoints.delete(address);else lab.breakpoints.add(address);if(state.build?.listing){const row=state.build.listing.find(r=>r.address===address&&r.bytes.length);if(row){if(lab.breakpoints.has(address)){state.sourceBreaks.add(row.line);state.sourceBreakAddresses.add(address);}else{state.sourceBreaks.delete(row.line);state.sourceBreakAddresses.delete(address);}}}renderSource();renderBreaks();if(state.view==='memory')renderDisassembly();autosave();}
function editDialog(title,description,fields,apply){pause();text('edit-title',title);text('edit-description',description);$('edit-fields').innerHTML=fields.map(f=>`<label>${esc(f.label)}<input id="edit-${esc(f.name)}" value="${esc(f.value)}" ${f.maxLength?'maxlength="'+f.maxLength+'"':''} autocomplete="off"></label>`).join('');editApply=apply;$('edit-dialog').showModal();const field=$('edit-fields').querySelector('input');field?.focus();field?.select();}
function parseEdit(name,max=65535){const raw=$('edit-'+name).value.trim().replace(/H$/i,'').replace(/^0x/i,'');if(!/^[a-f\d]+$/i.test(raw))throw new Error('Enter hexadecimal digits');const v=parseInt(raw,16);if(v>max)throw new Error('Value out of range');return v;}
function editMemory(address){text('memory-selected',hex(address,4)+'H');if(address<RAM_START)throw new Error('0000H–1FFFH is protected monitor ROM. Route interrupt vectors in Reference.');editDialog('Edit '+hex(address,4)+'H','Enter an 8-bit hexadecimal value.',[{name:'byte',label:'Byte (00–FF)',value:hex(lab.peek(address)),maxLength:3}],()=>lab.write(address,parseEdit('byte',255)));}

function initializeInterrupts(){$('interrupt-controls').innerHTML=[['TRAP','0024H','edge + level'],['RST75','003CH','rising edge'],['RST65','0034H','level'],['RST55','002CH','level'],['INTR','external','level']].map(([name,vector,type])=>`<div class="interrupt-row"><code>${name.replace('75','7.5').replace('65','6.5').replace('55','5.5')}</code><span>${vector} · ${type}</span><span class="mask-indicator" id="irq-mask-${name}"></span><label class="toggle-label"><input type="checkbox" id="irq-level-${name}" data-irq-level="${name}"> High</label><button class="button small" data-irq-pulse="${name}">Pulse</button></div>`).join('');}
function renderInterrupts(){for(const name of ['TRAP','RST75','RST65','RST55','INTR']){checked('irq-level-'+name,lab.cpu.lines[name]);text('irq-mask-'+name,name==='TRAP'?'NMI':name==='INTR'?(lab.cpu.inte?'ENABLED':'DISABLED'):(lab.cpu.masks&({RST75:4,RST65:2,RST55:1})[name])?'MASKED':'OPEN');$('irq-mask-'+name).classList.toggle('lime-text',name==='TRAP'||!['MASKED','DISABLED'].includes($('irq-mask-'+name).textContent));}}
function pulseInterrupt(name){lab.cpu.setLine(name,0);lab.cpu.setLine(name,1);if(name==='RST75'){lab.cpu.setLine(name,0);}else {const irq=lab.cpu.interrupt();lab.cpu.setLine(name,0);if(irq)log(irq.text);else notify(`${name} pulse was not accepted; check EI and SIM masks.`,true);}renderAll();}
function renderInstructions(){const q=$('instruction-search').value.trim().toUpperCase(),group=$('instruction-group').value;const items=INSTRUCTIONS.filter(e=>(group==='all'||e.group===group)&&(!q||[e.mnemonic,e.args.join(','),e.description,e.group].join(' ').toUpperCase().includes(q)));$('instruction-table').innerHTML='<thead><tr><th>INSTRUCTION</th><th>HEX</th><th>BYTES</th><th>T-STATES</th><th>FLAGS</th><th>FUNCTION</th></tr></thead><tbody>'+items.map(e=>`<tr><td>${e.mnemonic}${e.args.length?' '+e.args.map(a=>a==='a16'?'addr':a).join(', '):''}</td><td>${hex(e.opcode)}</td><td>${e.bytes}</td><td>${e.cycles[0]===e.cycles[1]?e.cycles[0]:e.cycles.join(' / ')}</td><td class="mono">${esc(e.flags)}</td><td>${esc(e.description)}</td></tr>`).join('')+'</tbody>';}
function updateWaveFrequency(){const n=+$('wave-samples').value,d=+$('wave-delay').value,period=n*((lab.mapping[0].space==='io'?41:44)+14*d)+24;text('wave-frequency',formatHz(lab.clock/period));}
function renderAll(){renderCPU();renderID();renderAnalog();if(state.view==='bench'){scope.drawMini();if(state.output==='console'||state.output==='listing')renderOutput();}if(state.view==='interface'){renderPPI();renderPeripherals();}if(state.view==='scope')scope.draw();if(state.view==='memory')renderMemory();if(state.view==='reference')renderInterrupts();}

function saveProject(){const controls=Object.fromEntries(all('#view-scope input,#view-scope select,#run-speed,#keep-halted').filter(e=>e.id).map(e=>[e.id,e.type==='checkbox'?e.checked:e.value]));const project={format:'8085-bench',version:1,source:$('source').value,fileName:state.fileName,dirty:state.dirty,sourceBreaks:[...state.sourceBreaks],machine:lab.snapshot(),controls,view:state.view};download(state.fileName.replace(/\.[^.]+$/,'')+'.85bench',JSON.stringify(project),'application/json');notify('Project saved with CPU, memory, peripherals and source.');}
function loadProject(data){if(data?.format!=='8085-bench'||data.version!==1||typeof data.source!=='string'||data.source.length>2000000||!Array.isArray(data.sourceBreaks)||!data.sourceBreaks.every(n=>Number.isInteger(n)&&n>0&&n<=100000))throw new Error('This is not a valid 8085 Bench project');const restored=new Lab();restored.restore(data.machine); // Validate before changing the live session.
  pause();lab.restore(restored.snapshot());$('source').value=data.source;state.fileName=String(data.fileName||'experiment.asm');text('source-name',state.fileName);state.build=assemble(data.source);state.dirty=!!data.dirty;state.imported=!state.build.ok;state.sourceBreaks=new Set(data.sourceBreaks);$('dirty-dot').style.display=state.dirty?'inline':'none';for(const [id,v]of Object.entries(data.controls||{})){const node=$(id);if(node?.matches('#view-scope input,#view-scope select,#run-speed,#keep-halted')){if(node.type==='checkbox')node.checked=!!v;else if(node.tagName==='SELECT'){if([...node.options].some(o=>o.value===String(v)))node.value=String(v);}else if(Number.isFinite(+v))node.value=String(v);}}scope.clear();scope.mode=$('scope-mode').value;syncSettings();renderSource();renderOutput();setView(['bench','interface','scope','memory','reference'].includes(data.view)?data.view:'bench');autosave();notify('Project restored. Execution is paused.');}
function loadImage(image,name){pause();lab.load({...image,ok:true,vectors:[]});const rows=[`; Imported ${name} · edit bytes or replace with assembly.`];for(let a=RAM_START;a<65536;){if(!image.written[a]){a++;continue;}rows.push('ORG '+hex(a,4)+'H');while(a<65536&&image.written[a]){const bytes=[];while(a<65536&&image.written[a]&&bytes.length<16)bytes.push(hex(image.memory[a++])+'H');rows.push('DB '+bytes.join(', '));}}rows.push('END '+hex(image.entry,4)+'H','');$('source').value=rows.join('\n');state.fileName=name.replace(/\.[^.]+$/,'')+'.asm';text('source-name',state.fileName);state.build=assemble($('source').value);state.imported=true;state.dirty=false;state.sourceBreaks.clear();state.sourceBreakAddresses.clear();$('dirty-dot').style.display='none';scope.clear();renderSource();setView('bench');log('Machine image loaded · PC '+hex(image.entry,4)+'H');autosave();}
async function importFile(file){if(!file)return;if(file.size>25*1024*1024)throw new Error('File is too large (limit 25 MB)');const suffix=file.name.split('.').at(-1).toLowerCase();if(suffix==='bin'){const bytes=new Uint8Array(await file.arrayBuffer());editDialog('Load binary into RAM',`${file.name} · ${bytes.length} bytes. Loading replaces user RAM. Select the load address.`,[{name:'address',label:'Address (hex)',value:'2000'}],()=>{const start=parseEdit('address');if(!bytes.length||start<RAM_START||start+bytes.length>65536)throw new Error('Binary must be nonempty and fit in 2000H–FFFFH');const image={memory:new Uint8Array(65536),written:new Uint8Array(65536),entry:start};image.memory.set(bytes,start);image.written.fill(1,start,start+bytes.length);loadImage(image,file.name);notify('Binary loaded.');});return;}
  const content=await file.text();if(suffix==='85bench'||suffix==='json'){loadProject(JSON.parse(content));return;}if(suffix==='hex'){loadImage(importHex(content),file.name);notify('Intel HEX loaded; ready to run.');return;}if(content.length>2000000)throw new Error('Source is too large (limit 2 million characters)');setSource(content,file.name);setView('bench');notify('Source opened. Assemble to load it into RAM.');}

// Stable controls are bound once. Dynamic board, editor and memory actions use delegation.
on('assemble-btn','click',()=>buildAndLoad());on('run-btn','click',run);on('step-btn','click',step);on('step-over','click',stepOver);on('reset-btn','click',reset);on('save-project','click',saveProject);on('import-btn','click',()=>$('file-input').click());on('file-input','change',async e=>{await importFile(e.target.files[0]);e.target.value='';});
on('source-export','click',()=>download(state.fileName,$('source').value));on('editor-expand','click',()=>$('source').closest('.editor-panel').classList.toggle('expanded'));
on('help-btn','click',()=>$('quick-start').showModal());on('help-close','click',()=>$('quick-start').close());on('help-done','click',()=>$('quick-start').close());
on('example-select','change',e=>loadExample(e.target.value));
on('source','input',()=>{pause();state.dirty=true;state.imported=false;$('dirty-dot').style.display='inline';renderSource();autosave();});on('source','scroll',syncEditorScroll);on('source','keyup',updateCaret);on('source','click',updateCaret);
on('source','keydown',e=>{if(e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('    ',start,end,'end');el.dispatchEvent(new Event('input'));}else if(e.key==='Enter'){const el=e.target,previous=el.value.slice(0,el.selectionStart).split('\n').at(-1),indent=/^\s*/.exec(previous)[0];if(indent){e.preventDefault();el.setRangeText('\n'+indent,el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input'));}}});
on('cpu-clock','change',e=>{if(state.running)pause('Paused to change CPU clock');lab.clock=+e.target.value;scope.clear();updateWaveFrequency();});
on('jump-pc','click',()=>{state.memoryPage=lab.cpu.pc&0xFF00;value('memory-address',hex(lab.cpu.pc,4));setView('memory');});
on('console-send','click',()=>{for(const c of $('console-input').value+'\r')lab.consoleIn.push(c.charCodeAt(0)&255);$('console-input').value='';notify('Keyboard input queued.');});on('console-input','keydown',e=>{if(e.key==='Enter')$('console-send').click();});
on('display-id','click',()=>{lab.displayID($('user-id').value);renderID();renderWiring();renderPPI();autosave();notify('ID displayed: PA '+lab.id.slice(0,2)+' · PB '+lab.id.slice(2,4)+' · PC '+lab.id.slice(4,6));});
on('user-id','input',e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,6);if(/^\d{6}$/.test(e.target.value)){lab.id=e.target.value;autosave();}});
on('id-code','click',()=>{const id=$('user-id').value;if(!/^\d{6}$/.test(id))throw new Error('Enter exactly six digits first');lab.id=id;setSource(idProgram(id,lab.mapping[1].base,lab.idActiveLow,lab.mapping[1].space),'my-id.asm');setView('bench');notify('ID program generated. Assemble and run to drive the LEDs.');});
on('analog-connected','change',e=>{lab.wiring.analogEnabled=e.target.checked;lab.sync();renderWiring();renderAll();});
on('restore-wiring','click',()=>{lab.mapping=[{space:'io',base:0x80},{space:'io',base:0x90}];lab.wiring={dac:'A',adc:'B',control:'C',analogEnabled:true,irq:'none'};lab.sync();syncSettings();renderAll();notify('Default I/O addresses and analog harness restored.');});
for(const port of ['dac','adc'])on('wire-'+port,'change',e=>{lab.wiring[port]=e.target.value;lab.wiring[port==='dac'?'adc':'dac']=e.target.value==='A'?'B':'A';value('wire-'+(port==='dac'?'adc':'dac'),lab.wiring[port==='dac'?'adc':'dac']);lab.sync();renderWiring();renderAll();});
on('wire-irq','change',e=>{const old=lab.wiring.irq;if(old!=='none')lab.cpu.setLine(old,0);lab.wiring.irq=e.target.value;lab.sync();});
on('adc-profile','change',e=>{lab.adc.profile=e.target.value;lab.adc.reset();if(lab.adc.profile==='0804')lab.adc.channel=0;lab.sync();$('manual-channel').disabled=lab.adc.profile==='0804';renderWiring();renderAll();notify(lab.adc.profile==='0804'?'ADC0804: PC3=/WR, PC0=/RD, PC7=/INTR; CS tied low.':'ADC0808: PC3=ALE+START, PC0–2=channel, PC7=EOC; OE tied high.');});
on('adc-vref','change',()=>{lab.adc.vref=numeric('adc-vref',.1,20);});on('adc-clock','change',()=>{lab.adc.clock=numeric('adc-clock',10,1280)*1000;renderPeripherals();});on('adc-convert','click',manualConversion);on('advance-time','click',()=>{lab.idle(.001);renderAll();});
on('dac-profile','change',e=>{lab.dac.profile=e.target.value;renderWiring();renderAll();});for(const [id,property,min,max]of [['dac-vref','reference',.1,20],['dac-rref','rref',100,100000],['dac-rload','rload',100,100000]])on(id,'change',()=>{lab.dac[property]=numeric(id,min,max);renderAll();});on('dac-bipolar','change',e=>{lab.dac.bipolar=e.target.checked;renderAll();});on('dac-manual','input',e=>{if(!lab.wiring.analogEnabled)throw new Error('Connect the analog harness to drive the DAC');const p=lab.wiring.dac==='A'?0:1;const cw=lab.wiring.dac==='A'?0x8A:0x98;if(lab.ppis[0].control!==cw)writePPI(0,3,cw);writePPI(0,p,+e.target.value);lab.sample(lab.time);renderAll();});
for(const [key,min,max]of [['frequency',.01,100000],['amplitude',0,20],['offset',-20,20],['duty',1,99],['phase',-36000,36000],['dc',-20,20]])on('gen-'+key,'change',()=>{lab.generator[key]=numeric('gen-'+key,min,max);});on('gen-type','change',e=>{lab.generator.type=e.target.value;});
for(const id of ['wave-type','wave-samples','wave-delay','wave-low','wave-high'])on(id,'input',updateWaveFrequency);
on('wave-generate','click',()=>{const samples=+$('wave-samples').value,delay=numeric('wave-delay',1,255),low=numeric('wave-low',0,255),high=numeric('wave-high',0,255);if(![delay,low,high].every(Number.isInteger)||low>=high)throw new Error('Use integer codes and delay; minimum must be below maximum');lab.wiring={...lab.wiring,dac:'A',adc:'B',analogEnabled:true};setSource(waveProgram($('wave-type').value,{...lab.mapping[0],samples,delay,low,high}),$('wave-type').value+'-wave.asm');syncSettings();setView('bench');notify('DAC waveform program generated. Assemble and run.');});
on('scope-mode','change',e=>{scope.mode=e.target.value;scope.draw();});on('scope-freeze','click',()=>{scope.freeze();scope.draw();});on('scope-arm','click',()=>{scope.arm();scope.draw();});on('scope-clear','click',()=>{scope.clear();scope.draw();});on('scope-autoset','click',()=>scope.autoset());on('scope-rate','change',e=>{lab.scopeRate=+e.target.value;scope.clear();scope.draw();});for(const id of ['scope-ch1','scope-ch2','scope-vdiv','scope-center','scope-tdiv','scope-trigger-mode','scope-trigger-source','scope-edge','scope-level','logic-source'])on(id,'change',()=>{if(id!=='logic-source')scope.arm();scope.draw();});
on('scope-csv','click',()=>{const p=lab.scope.points(),keys=['t','input','dac','adc','a','b','c','ledA','ledB','ledC','sid','sod','eoc'];download('scope-capture.csv',keys.join(',')+'\n'+p.map(row=>keys.map(k=>row[k]).join(',')).join('\n'),'text/csv');});on('scope-png','click',()=>{$('scope-canvas').toBlob(blob=>{if(blob)download('oscilloscope.png',blob);});});
on('memory-go','click',()=>{state.memoryPage=readHex('memory-address')&0xFF00;renderMemory();});on('memory-address','keydown',e=>{if(e.key==='Enter')$('memory-go').click();});for(const [id,delta]of [['memory-prev',-256],['memory-next',256]])on(id,'click',()=>{state.memoryPage=(state.memoryPage+delta+65536)&0xFF00;value('memory-address',hex(state.memoryPage,4));renderMemory();});on('follow-pc','change',renderDisassembly);
on('poke-write','click',()=>{const start=readHex('poke-address'),raw=$('poke-data').value.trim();if(!/^(?:[\da-f]{2})(?:[\s,]+[\da-f]{2})*$/i.test(raw))throw new Error('Enter bytes as two hex digits separated by spaces');const bytes=raw.split(/[\s,]+/).map(s=>parseInt(s,16));if(start<RAM_START||start+bytes.length>65536)throw new Error('Writes must fit in 2000H–FFFFH');pause();bytes.forEach((b,i)=>lab.write(start+i,b));renderMemory();notify('Wrote '+bytes.length+' bytes.');});
on('fill-memory','click',()=>editDialog('Fill user RAM range','This overwrites the selected inclusive range.',[{name:'start',label:'Start (hex)',value:hex(state.memoryPage,4)},{name:'end',label:'End (hex)',value:hex(state.memoryPage+255,4)},{name:'fill',label:'Byte (hex)',value:'00'}],()=>{const start=parseEdit('start'),end=parseEdit('end'),fill=parseEdit('fill',255);if(start<RAM_START||end<start)throw new Error('Range must be in user RAM, with end ≥ start');for(let a=start;a<=end;a++)lab.write(a,fill);notify('Filled '+(end-start+1)+' RAM bytes.');}));
on('export-hex','click',()=>download('user-memory.hex',exportHex(lab.memory,null)));on('export-bin','click',()=>download('ram-2000-ffff.bin',lab.memory.slice(RAM_START),'application/octet-stream'));
on('break-add','click',()=>{const address=readHex('break-address'),kind=$('break-kind').value;if(kind==='execute'){if(!lab.breakpoints.has(address))toggleBreak(address);}else lab.watchpoints.set(address,kind);renderBreaks();renderSource();});on('clear-breaks','click',()=>{lab.breakpoints.clear();lab.watchpoints.clear();state.sourceBreaks.clear();state.sourceBreakAddresses.clear();renderSource();renderBreaks();renderDisassembly();});
on('io-in','click',()=>{const p=readHex('io-address',255),v=lab.input(p);value('io-value',hex(v));renderMemory();notify('IN '+hex(p)+'H = '+hex(v)+'H');});on('io-out','click',()=>{lab.output(readHex('io-address',255),readHex('io-value',255));renderAll();});on('io-address','change',renderIO);
on('trace-enabled','change',e=>{lab.traceEnabled=e.target.checked;});on('trace-filter','change',renderTrace);on('trace-clear','click',()=>{lab.trace.clear();renderTrace();});on('trace-export','click',()=>download('bus-trace.csv','seconds,tstates,type,address,data,device\n'+lab.trace.points().map(p=>[p.t,p.cycles,p.type,hex(p.address,4),hex(p.value),p.device].join(',')).join('\n'),'text/csv'));
on('intr-vector','change',e=>{lab.cpu.intrOpcode=+e.target.value;});on('intr-call','change',()=>{lab.cpu.intrAddress=readHex('intr-call');});on('sid-input','change',e=>{lab.cpu.sid=+e.target.checked;});on('cpu-hold','change',e=>{lab.cpu.hold=e.target.checked;renderRunState();});on('cpu-waits','change',()=>{lab.cpu.waitStates=Math.floor(numeric('cpu-waits',0,1000));});
on('vector-set','click',()=>{const target=readHex('vector-target');if(target<RAM_START)throw new Error('Choose an interrupt handler in user RAM (2000H–FFFFH)');lab.setVector(+$('vector-address').value,target);notify('Monitor vector now jumps to '+hex(target,4)+'H');});on('instruction-search','input',renderInstructions);on('instruction-group','change',renderInstructions);
on('edit-cancel','click',()=>$('edit-dialog').close());on('edit-form','submit',e=>{e.preventDefault();editApply?.();$('edit-dialog').close();renderAll();});
document.addEventListener('click',e=>{try{const b=e.target.closest('button,[data-io],.line-number[data-line]');if(!b)return;if(b.dataset.view)setView(b.dataset.view);else if(b.dataset.goto)setView(b.dataset.goto);else if(b.dataset.output){state.output=b.dataset.output;all('[data-output]').forEach(el=>el.classList.toggle('active',el===b));renderOutput();}
    else if(b.dataset.example)loadExample(b.dataset.example);
    else if(b.dataset.line){const line=+b.dataset.line;if(state.sourceBreaks.has(line))state.sourceBreaks.delete(line);else state.sourceBreaks.add(line);const r=state.build?.listing?.find(r=>r.line===line&&r.bytes.length);if(r&&!state.dirty){if(state.sourceBreaks.has(line)){lab.breakpoints.add(r.address);state.sourceBreakAddresses.add(r.address);}else{lab.breakpoints.delete(r.address);state.sourceBreakAddresses.delete(r.address);}}renderSource();autosave();}
    else if(b.dataset.errorLine){const line=+b.dataset.errorLine,el=$('source');el.focus();const index=el.value.split('\n').slice(0,line-1).reduce((n,s)=>n+s.length+1,0);el.setSelectionRange(index,index+el.value.split('\n')[line-1].length);el.scrollTop=Math.max(0,(line-3)*23);syncEditorScroll();}
    else if(b.dataset.register){const n=b.dataset.register,current=n==='PC'?lab.cpu.pc:n==='SP'?lab.cpu.sp:n==='F'?lab.cpu.flags:lab.cpu.r[n];editDialog('Edit register '+n,'Enter a hexadecimal value.',[{name:'register',label:n+' (hex)',value:hex(current,n==='PC'||n==='SP'?4:2)}],()=>{const v=parseEdit('register',n==='PC'||n==='SP'?65535:255);if(n==='PC'){lab.cpu.pc=v;lab.cpu.halted=false;lab.cpu.fault=null;}else if(n==='SP')lab.cpu.sp=v;else if(n==='F')lab.cpu.flags=v;else lab.cpu.r[n]=v;});}
    else if(b.dataset.flag){lab.cpu.f[b.dataset.flag]^=1;renderCPU();}
    else if(b.dataset.ppiAction)ppiAction(b);
    else if(b.dataset.memory)editMemory(+b.dataset.memory);
    else if(b.dataset.breakpoint)toggleBreak(+b.dataset.breakpoint);
    else if(b.dataset.removeBreak){const a=+b.dataset.removeBreak;if(b.dataset.kind==='execute')toggleBreak(a);else lab.watchpoints.delete(a);renderBreaks();renderDisassembly();}
    else if(b.dataset.io){value('io-address',hex(+b.dataset.io));value('io-value',hex(lab.externalPorts[+b.dataset.io]));}
    else if(b.dataset.irqPulse)pulseInterrupt(b.dataset.irqPulse);
  }catch(error){reportError(error);}finally{state.needsDraw=true;}});
document.addEventListener('change',e=>{if(e.target.dataset.irqLevel){lab.cpu.setLine(e.target.dataset.irqLevel,+e.target.checked);renderInterrupts();}else if(e.target.id==='id-active-low'){lab.idActiveLow=e.target.checked;renderID();}state.needsDraw=true;});
document.addEventListener('keydown',e=>{try{if(e.target.matches('.line-number')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();}else if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();buildAndLoad();}else if(e.key==='F5'){e.preventDefault();run();}else if(e.key==='F10'){e.preventDefault();if(e.shiftKey)stepOver();else step();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();}else if(e.key==='Escape'){$('source').closest('.editor-panel').classList.remove('expanded');}}catch(error){pause();reportError(error);}});
window.addEventListener('resize',()=>{scope.drawMini();if(state.view==='scope')scope.draw();});
window.addEventListener('beforeunload',()=>{try{localStorage.setItem('8085-bench-draft',JSON.stringify({source:$('source').value,id:lab.id,fileName:state.fileName,sourceBreaks:[...state.sourceBreaks]}));}catch{}});

function frame(now){const elapsed=Math.min(100,now-(state.lastFrame||now));state.lastFrame=now;if(state.running){const pace=$('run-speed').value,start=performance.now(),startCycles=lab.cpu.cycles;let count=0,budget=pace==='normal'?Math.floor(elapsed*50):pace==='slow'?Math.floor((state.slowCredit+=elapsed)/50):Infinity;if(pace==='slow')state.slowCredit%=50;
    try{while(state.running&&count<budget&&performance.now()-start<9){if(pace==='realtime'&&lab.cpu.cycles-startCycles>=elapsed*lab.clock/1000)break;
      if(lab.breakpoints.has(lab.cpu.pc)&&state.skipBreakpoint!==lab.cpu.pc&&!lab.cpu.halted){pause('Breakpoint at '+hex(lab.cpu.pc,4)+'H');scrollToPC();break;}
      if(state.temporaryBreak&&lab.cpu.pc===state.temporaryBreak.pc&&lab.cpu.sp===state.temporaryBreak.sp){pause('Stepped over · '+hex(lab.cpu.pc,4)+'H');scrollToPC();break;}
      state.skipBreakpoint=null;lab.watchHit=null;
      if(lab.cpu.halted&&pace!=='slow'){const irq=lab.cpu.interrupt();if(!irq){if(!$('keep-halted').checked){pause('CPU halted at '+hex(lab.cpu.pc,4)+'H');break;}lab.idle(pace==='fast'?.0001:Math.max(.000001,Math.min(.001,elapsed/1000)));count+=100;continue;}}
      else lab.cpu.step();count++;
      if(lab.watchHit){const hit=lab.watchHit;pause(`${hit.type==='r'?'Read':'Write'} watchpoint at ${hex(hit.address,4)}H`);scrollToPC();break;}
    }}catch(error){pause();lab.cpu.fault=error.message;reportError(error);log(error.message,'error');}
  }
  if(now-state.lastDraw>110&&(state.running||state.needsDraw)){renderAll();state.lastDraw=now;state.needsDraw=false;}requestAnimationFrame(frame);
}

initializeRegisters();initializeID();initializePPI();initializeChannels();initializeInterrupts();
$('example-select').insertAdjacentHTML('beforeend',EXAMPLES.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join(''));
$('example-cards').innerHTML=EXAMPLES.map((e,i)=>`<button class="example-card" data-example="${e.id}"><small>EXPERIMENT ${String(i+1).padStart(2,'0')} ↗</small><b>${esc(e.name)}</b><span>${esc(e.description)}</span></button>`).join('');
let draft;try{draft=JSON.parse(localStorage.getItem('8085-bench-draft'));}catch{}
$('source').value=typeof draft?.source==='string'?draft.source:EXAMPLES[0].source;if(/^\d{6}$/.test(draft?.id||''))lab.id=draft.id;if(typeof draft?.fileName==='string')state.fileName=draft.fileName;state.sourceBreaks=new Set(draft?.sourceBreaks||[]);text('source-name',state.fileName);renderSource();syncSettings();renderInstructions();buildAndLoad(true);renderAll();requestAnimationFrame(frame);
